"""Gaps, third run. Every count is a command, never a result; no pointer to a disposable database or
to a gap id this run did not get back from the writer. Returned ids are printed and saved."""
import json
from common import run, STEM, SC

LATEST = ("with latest as (select a.* from term_adjudications a where a.adjudication_id=(select max(adjudication_id) "
          "from term_adjudications b where b.observation_id=a.observation_id)) ")
PW = 'scratchpad/session_2026-11-13-edmonton-checklist-pass/parked-writes.jsonl'
G = [
 ('log-search-subject', 'SW', 'P3', 'log-search demands a subject (--slug, --parameter or --mined-ref-id) even for --origin owner-supplied, where no search ran. The owner-supplied admission of REF-01037 carries --slug stair-ramp-threshold-biomechanics-accessibility only to satisfy the writer, and its findings note says so (select exec_id, slug, findings_note from search_executions where exec_id in (select exec_id from search_admissions where ref_id=\'REF-01037\')). Writer defect; a tooling pull request (rule 10).', []),
 ('mining-forward', 'SW', 'P3', 'log-mining cannot record a deferred forward (cited-by) direction once a backward pass has set evidence_sources.citation_mining_status to mined: the writer refuses, "That column is ONE flag for BOTH directions (GAP-015/GAP-022, unruled)". REF-01037 has its backward pass logged; its forward pass was not run (an owner-supplied, from-evidence batch) and no probe of any citation index was made, and that cannot be recorded. Writer defect; a tooling pull request (rule 10).', []),
 ('engine-text', 'SW', 'P2', 'The engine (scripts/assess/assess_cell.py, gap_account) writes into a pending cell\'s gap text three things a reader takes as facts and that are not: (1) "from N source(s)": N is n_sources, the value-supplying sources the engine gathers, not the distinct sources holding extractions in the lens; count those with select count(distinct e.ref_id) from source_value_extractions e join v_live_lens_links l using(extraction_id) where e.parameter_id=<P> and l.<lens column>=<code>. (2) "none of those sources qualified to anchor - disqualified, or tier not derivable from their own (evidence_type, scope)": the same report\'s source_records can read tier_consistent true and conditioning DOWN-WEIGHTED for every source (a grey tier-3 source is simply not an anchoring tier), so the stated cause is untrue there; read source_records, skimmed_findings and needs_population_assessment in the --report-json instead. (3) The regulatory branch (G1, `elif regulatory:`) runs whenever no anchor and no T3-clinical source exists and any T4-6 source is in the lens, and then writes regulatory_stratum_only=1, code_floor_only by T6 alone and design_scale universal, although grey tier-3 sources are in the same lens. Seen on REF-01037\'s cells (parameters 5 and 9 under MOB; parameter 12 under A-EFFORT). Tool defect: not patched in a research batch (rule 10); the gap text goes into the batch as the engine wrote it.', []),
 ('pub-year', 'SW', 'P3', 'No sanctioned writer holds the basis of evidence_sources.pub_year, and add-source takes no notes: add-source has no flag for pub_year_note, amend-source refuses it ("not an amendable judgement field"), and correct-source takes only payload-backed fields. REF-01037 stores pub_year 2022 with no basis. The basis: 2022 is the PDF\'s own CreationDate (D:20220324091437-06\'00\', read with PyMuPDF from retrieval-log/session_2026-11-13-edmonton-checklist-pass/1a117aff4c5947a8.pdf), the build date of this file; no publication date is printed. The PDF\'s page-1 link annotation to its own URL carries the stamp cb=1631580961, which decodes to 2021-09-14, so 2022 may not be the publication year. Writer gap; a tooling pull request (rule 10), then the basis is written through the new verb.', []),
 ('follow-up-reason', 'SW', 'P3', 'raise-follow-up accepts only two reasons (absence-needs-tested-value, read-outside-admitting-purpose), so an extraction whose printed figure is ambiguous has no follow-up to carry it. REF-01037 item 5.3 prints "optimal turning radius of 1500x1500mm" (a radius, a diameter or the side of a square); its extraction on parameter 5 (select extraction_id from source_value_extractions where ref_id=\'REF-01037\' and parameter_id=5 and figure_role=\'claim\') stores the side, 1500, with the ambiguity in notes only; --value-as-written is refused because the quote writes the number as a numeral, which is right. Writer gap.', ['--parameter', '5']),
 ('harm', 'EG', 'P2', 'R7: harms or hazards REF-01037 states, tied to no held parameter, in the source\'s own words: item 1.5 "The more painted surface, the more likely pavement will become slippery"; item 4.3 "Avoid single isolated steps"; item 4.5 "Tactile strips under the stairs on the ground and a contrasting colour on the back of the stairwell above the tactile strips to alert a potential safety hazard"; item 6.5 "(able to open doors without backing onto ramp)"; item 8.2 "so persons who are blind do not become disoriented"; item 8.5 "insulate any exposed pipes"; item 8.6 "toilet paper reachable without leaning too far off toilet"; item 11.2 "grey colours should be avoided as they blend into the general background". Each is held as an observation; the owner-supplied search carries harm_finding=1. A judgment row waits on a parameter that holds the quantity (OD-50) or on a home for element provisions (OD-49 part b).', []),
 ('parked', 'DEC', 'P2', 'OD-47 (open): what lens a figure carries when its clause names no person, function or need. REF-01037 figures whose clause names no one are NOT written (OD-31 forbids ALL as an identity; D-0182 needs at least one lens; the lens writer needs words that warrant a code). Each is parked as the exact db.py add-extraction argv, lens blank, waits_on OD-47, with its condition_on edges, in ' + PW + ' (kind "extraction"; count them: grep -c \'"kind": "extraction"\' on that file). The same file holds the source\'s magenta-beside-blue pairings (kind "pairing"), which wait on a relation kind, not on OD-47. Replay through the writer once answered (rule 10; OD-54 reading a).', []),
 ('direction', 'EG', 'P2', 'Accessibility direction for parameters 5 (turning circle) and 9 (door width) is not set (select parameter_id from base_parameters where accessibility_direction is null). REF-01037 page 1 states which way is better for both ("a wider turning radius and wider doors are required by many wheelchairs and scooters today"), held as harm findings with insufficient edges. Whether a grey committee\'s assertion sets a direction (set-parameter-direction --ref-id) is the judging session\'s call, deliberately not made in this batch and to be named in the pull request.', []),
 ('deferred', 'EG', 'P2', 'R4: REF-01037 phrases adjudicated DEFERRED have no reader yet (T-079\'s v_deferred_acts is to gain an adjudication arm). Each rationale says why it is held: colour contrast against TERM-011 (unsettled on this source); the path-of-travel phrases (OD-52); a quantity with no term or parameter (OD-50; this batch mints no term); an element with no held term (this batch mints no term: a withheld act, not an unsettled reading, against DEFERRED\'s schema meaning); a group phrase (the catalogue holds no term for the group; an adjudication cannot name an identity code). Derive the list: ' + LATEST + "select o.observation_id, o.surface_form, o.locator, substr(l.rationale,1,80) from observed_terms o join latest l using(observation_id) where o.ref_id='REF-01037' and l.outcome='DEFERRED'. Counts: " + LATEST + "select coalesce(l.outcome,'UNADJUDICATED'), count(*) from observed_terms o left join latest l using(observation_id) where o.ref_id='REF-01037' group by 1.", []),
 ('jurisdiction', 'EG', 'P3', 'REF-01037 is a City of Edmonton document and its figures are recorded under country code CA: base_jurisdictions holds no sub-national code for Alberta or Edmonton (T-024 built the registry; add-jurisdiction admits one with an approval reference).', ['--jurisdiction', 'CA']),
 ('leads', 'RP', 'P2', 'Backward-mining leads named by REF-01037 and staged REFERENCE-ONLY, not retrieved: the Safety Codes Council Barrier-Free Design Guide (Aug 2019 PDF), the City of Edmonton Access Design Guide, Policy C602, and the Alberta Building Code (no edition stated). The Alberta code is the presumed root of every figure the source marks Code (required) (OR-19; those rows are root_type untraced); its admission re-roots them. Derive the leads: select ref_id, title from source_locators where recovered_from like \'REF-01037%\'.', []),
 ('text-defects', 'SW', 'P3', 'REF-01037 text defects as printed, recorded without correction: item 6.2 "With the ramp at any point shall not be less than 1500mm/60”" has no subject noun, so its 1500 mm is held as an observation only (DEFERRED: what it measures cannot be settled on this source) and is neither written nor parked; item 5.3 prints "at least 910 – 915mm" and a "1500x1500mm" turning radius; item 2.10 prints a corridor width under the ENTRANCES heading; items 4.7 and 7.1 repeat the handrail rule. A reviewer reads the page render before relying on the rows that carry them.', []),
 ('relation-kind', 'SW', 'P2', 'No relation kind in extraction_relations.relation states a source\'s pairing of a higher figure it recommends with the floor (or a stricter ceiling with the code ceiling) it prints beside it. The nearest, exceeds, means "the source asserts the referent\'s value is more than needed" (table DDL), the reverse of the source; delta_over is an increment, confirms an independent measurement. An earlier run of this digest wrote 920 exceeds 850 for REF-01037 item 2.3, and extraction_relations_integrity passed it, because that check reads an edge\'s shape (its CHECKs and referents), not its meaning against the source. The pairings are parked as relate-extraction argv with the relation left as a marked hole (' + PW + ', kind "pairing": items 2.3, 2.10, 6.1). Writer gap (a relation kind, by data with its meaning) and check gap; a tooling pull request (rule 10).', []),
 ('co1-pass', 'EG', 'P2', 'The Co-1, Tier 2 and Co-2 pass for the topic of slug stair-ramp-threshold-biomechanics-accessibility (and the other four slugs REF-01037 is linked to) was not performed by the REF-01037 batch. Its owner-supplied search carries CO1-NOT-APPLICABLE, which says only that an owner-supplied, from-evidence admission runs no search and so owes no Co-1 or Co-2 search itself; it is not a Co-1 pass. The pass belongs to the research stage. add-gap takes no --slug, so the slug is named here.', []),
 ('r16', 'DEC', 'P2', 'R16 is red for the REF-01037 batch, deliberately: observations that name a held term which is neither a parameter nor declined are adjudicated NAMES-EXISTING to it, because that is what they name, and the terms are neither promoted nor declined. Whether a single-source batch may decline held terms is the owner\'s open question OD-53. List the terms: select distinct a.term_id, t.canonical_en from term_adjudications a join observed_terms o using(observation_id) join terms t using(term_id) where o.ref_id=\'REF-01037\' and not exists (select 1 from base_parameters p where p.term_id=a.term_id) and not exists (select 1 from parameter_declinations d where d.term_id=a.term_id and d.revoked_at is null). The batch is non-compliant on R16 pending OD-53.', []),
]
ids = {}
for key, cat, pri, desc, extra in G:
    rc, o = run('add-gap', '--category', cat, '--priority', pri, '--description', desc, '--session', STEM, *extra)
    gid = None
    try:
        gid = json.loads(o[o.index('{'):]).get('gap_id')
    except Exception:
        pass
    ids[key] = gid
    print(key, cat, pri, rc, gid, '' if rc == 0 else o[-300:])
json.dump(ids, open(SC + '/gap-ids.json', 'w'), indent=1)
